package com.ligamunicipal.api.service;
import com.ligamunicipal.api.model.*; import com.ligamunicipal.api.repo.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.*; import java.time.*; import java.util.*;
@Service public class LigaService {
 public final EquipoRepository equipos; public final JugadorPlantillaRepository jugadores; public final PartidoJornadaRepository partidos; public final MiembroEquipoRepository miembros; public final UsuarioRepository usuarios; public final AsistenciaPartidoRepository asistencias; public final AlineacionFantasyRepository alineaciones; public final VotoJornadaRepository votos; public final PropuestaPrecioInicialRepository propuestas; public final HistorialMercadoRepository historialMercado; public final HistorialRankingRepository historialRanking; public final InitialDataService initialData;
 public LigaService(EquipoRepository e,JugadorPlantillaRepository j,PartidoJornadaRepository p,MiembroEquipoRepository m,UsuarioRepository u,AsistenciaPartidoRepository a,AlineacionFantasyRepository al,VotoJornadaRepository v,PropuestaPrecioInicialRepository pp,HistorialMercadoRepository hm,HistorialRankingRepository hr,InitialDataService id){equipos=e;jugadores=j;partidos=p;miembros=m;usuarios=u;asistencias=a;alineaciones=al;votos=v;propuestas=pp;historialMercado=hm;historialRanking=hr;initialData=id;}
 public List<Equipo> equipos(UUID usuarioId){return miembros.findByUsuarioId(usuarioId).stream().map(m->m.equipo).toList();} public List<Equipo> equipos(){return equipos.findAll();} public List<JugadorPlantilla> plantilla(UUID id){return jugadores.findByEquipoId(id);} public List<PartidoJornada> jornadas(UUID id){return partidos.findByEquipoId(id);}
 public Usuario login(String email,String password){return usuarios.findByEmailIgnoreCase(email==null?"":email).filter(u->u.password.equals(password==null?"":password)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciales invalidas"));}
 @Transactional public Equipo crearEquipo(Equipo e,UUID usuarioId,boolean esJugadorReal){var usuario=usuarios.findById(usuarioId).orElseThrow(); if(e.codigoInvitacion==null)e.codigoInvitacion=UUID.randomUUID().toString().substring(0,8).toUpperCase(); if(e.tamanoAlineacion==0||e.formato==FormatoEquipo.FUTBOL_7&&e.tamanoAlineacion<7)e.tamanoAlineacion=sugerirTamanoAlineacion(e.formato); if(e.presupuestoMaximo==null||e.presupuestoMaximo.signum()<=0)e.presupuestoMaximo=BigDecimal.valueOf(36); var equipo=equipos.save(e);var miembro=new MiembroEquipo();miembro.equipo=equipo;miembro.usuario=usuario;miembro.rol=RolMiembro.ADMIN;miembro.esJugadorReal=esJugadorReal;miembros.save(miembro);initialData.ensureInitialPlayers(equipo);return equipo;}
 private int sugerirTamanoAlineacion(FormatoEquipo formato){return switch(formato){case FUTBOL_5,FUTBOL_SALA -> 3; case FUTBOL_7 -> 7; case FUTBOL_11 -> 5;};}
 public MiembroEquipo requireAdmin(UUID equipoId,UUID usuarioId){return miembros.findByEquipoIdAndUsuarioId(equipoId,usuarioId).filter(m->m.rol==RolMiembro.ADMIN).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Se requiere ser administrador del equipo"));}
 public JugadorPlantilla crearJugador(UUID equipoId,JugadorPlantilla j,UUID usuarioId){requireAdmin(equipoId,usuarioId);j.equipo=equipos.findById(equipoId).orElseThrow(); return jugadores.save(j);} public PartidoJornada crearPartido(UUID equipoId,PartidoJornada p,UUID usuarioId){requireAdmin(equipoId,usuarioId);p.equipo=equipos.findById(equipoId).orElseThrow();return partidos.save(p);}
 @Transactional public PropuestaPrecioInicial proponerPrecio(UUID equipoId,UUID jugadorId,BigDecimal valor,UUID usuarioId){var miembro=miembros.findByEquipoIdAndUsuarioId(equipoId,usuarioId).orElseThrow();var equipo=equipos.findById(equipoId).orElseThrow();if(!equipo.encuestaPreciosAbierta)throw new ResponseStatusException(HttpStatus.CONFLICT,"La encuesta esta cerrada");var jugador=jugadores.findById(jugadorId).orElseThrow();if(!jugador.equipo.id.equals(equipoId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Jugador no encontrado");var propuesta=propuestas.findByJugadorIdAndMiembroId(jugadorId,miembro.id).orElseGet(PropuestaPrecioInicial::new);propuesta.jugador=jugador;propuesta.miembro=miembro;propuesta.valorPropuesto=valor;return propuestas.save(propuesta);}
 @Transactional public Equipo abrirEncuesta(UUID equipoId,UUID usuarioId){requireAdmin(equipoId,usuarioId);var e=equipos.findById(equipoId).orElseThrow();e.encuestaPreciosAbierta=true;return equipos.save(e);}
 @Transactional public Equipo cerrarEncuesta(UUID equipoId,UUID usuarioId){requireAdmin(equipoId,usuarioId);var e=equipos.findById(equipoId).orElseThrow();for(var jugador:jugadores.findByEquipoId(equipoId)){var ps=propuestas.findByJugadorEquipoId(equipoId).stream().filter(p->p.jugador.id.equals(jugador.id)).toList();if(!ps.isEmpty()){jugador.valorMercadoActual=ps.stream().map(p->p.valorPropuesto).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(ps.size()),2,RoundingMode.HALF_UP);jugadores.save(jugador);var h=new HistorialMercado();h.jugador=jugador;h.valorMercado=jugador.valorMercadoActual;historialMercado.save(h);}}e.encuestaPreciosAbierta=false;return equipos.save(e);}
 @Transactional public AsistenciaPartido asistencia(UUID partidoId,UUID jugadorId,EstadoAsistencia estado,UUID usuarioId){var partido=partidos.findById(partidoId).orElseThrow();var jugador=jugadores.findById(jugadorId).orElseThrow();if(!jugador.equipo.id.equals(partido.equipo.id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Jugador no encontrado");var miembro=miembros.findByEquipoIdAndUsuarioId(partido.equipo.id,usuarioId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"No perteneces al equipo"));if(miembro.rol!=RolMiembro.ADMIN&&(miembro.jugadorPlantilla==null||!miembro.jugadorPlantilla.id.equals(jugadorId)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"No puedes modificar esta asistencia");var a=asistencias.findByPartidoIdAndJugadorId(partidoId,jugadorId).orElseGet(AsistenciaPartido::new);a.partido=partido;a.jugador=jugador;a.estadoAsistencia=estado;a.fechaRespuesta=Instant.now();return asistencias.save(a);}
 @Transactional public AlineacionFantasy guardarAlineacion(UUID partidoId,UUID miembroId,AlineacionFantasy recibida,UUID usuarioId){var p=partidos.findById(partidoId).orElseThrow(); if(p.estado==EstadoPartido.CERRADO||!p.fechaHoraPartido.isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"La jornada esta bloqueada"); var miembro=miembros.findById(miembroId).orElseThrow(); if(!miembro.equipo.id.equals(p.equipo.id)||!miembro.usuario.id.equals(usuarioId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"No puedes guardar esta alineacion"); var a=alineaciones.findByMiembroIdAndPartidoId(miembroId,partidoId).orElseGet(AlineacionFantasy::new); a.partido=p;a.miembro=miembro;a.formacion=recibida.formacion; if(recibida.detalles==null||recibida.detalles.size()!=miembro.equipo.tamanoAlineacion||recibida.detalles.stream().filter(d->d.esCapitan).count()!=1)throw new IllegalArgumentException("La alineacion no coincide con el formato o no tiene exactamente un capitan"); var esperado=distribucionFormacion(recibida.formacion); a.detalles.clear(); var ids=new HashSet<UUID>(); BigDecimal total=BigDecimal.ZERO; var usados=new EnumMap<Posicion,Integer>(Posicion.class); for(var detalle:recibida.detalles){var jugador=jugadores.findById(detalle.jugador.id).orElseThrow();if(!jugador.equipo.id.equals(p.equipo.id)||!ids.add(jugador.id)||detalle.posicionAsignada==null||(jugador.posicionPrincipal!=detalle.posicionAsignada&&jugador.posicionSecundaria!=detalle.posicionAsignada))throw new IllegalArgumentException("Jugador, posicion o polivalencia no validos");usados.merge(detalle.posicionAsignada,1,Integer::sum);detalle.jugador=jugador;total=total.add(jugador.valorMercadoActual);detalle.alineacion=a;a.detalles.add(detalle);}if(!esperado.equals(usados))throw new IllegalArgumentException("La distribucion no coincide con la formacion"); if(total.compareTo(a.miembro.equipo.presupuestoMaximo)>0)throw new IllegalArgumentException("Presupuesto excedido");a.presupuestoGastado=total; a.fechaGuardado=Instant.now();return alineaciones.save(a);}
 private Map<Posicion,Integer> distribucionFormacion(String formacion){var partes=Arrays.stream(Optional.ofNullable(formacion).orElse("").split("-")).mapToInt(Integer::parseInt).toArray();if(partes.length!=4)throw new IllegalArgumentException("Formacion no valida");var esperado=new EnumMap<Posicion,Integer>(Posicion.class);esperado.put(Posicion.POR,partes[0]);esperado.put(Posicion.DEF,partes[1]);esperado.put(Posicion.CEN,partes[2]);esperado.put(Posicion.DEL,partes[3]);return esperado;}
 public List<Map<String,Object>> estadoPartido(UUID partidoId,UUID usuarioId){var partido=partidos.findById(partidoId).orElseThrow();var miembro=miembros.findByEquipoIdAndUsuarioId(partido.equipo.id,usuarioId).orElseThrow();return jugadores.findByEquipoId(partido.equipo.id).stream().map(j->{Map<String,Object> estado=new HashMap<>();estado.put("jugador",j);estado.put("asistencia",asistencias.findByPartidoIdAndJugadorId(partidoId,j.id).map(a->a.estadoAsistencia).orElse(EstadoAsistencia.SIN_CONFIRMAR));estado.put("historial",historialMercado.findByJugadorIdOrderByFechaRegistroAsc(j.id));estado.put("miembroId",miembro.id);estado.put("jugadorMiembroId",miembro.jugadorPlantilla==null?null:miembro.jugadorPlantilla.id);return estado;}).toList();}
 public List<com.ligamunicipal.api.web.RankingItemDto> ranking(UUID equipoId,UUID usuarioId){var ordenados=miembros.findByEquipoId(equipoId).stream().sorted(Comparator.comparing((MiembroEquipo m)->m.puntosTotales).reversed().thenComparing(m->m.id)).toList();return java.util.stream.IntStream.range(0,ordenados.size()).mapToObj(i->{var m=ordenados.get(i);var anterior=historialRanking.findTopByMiembroIdOrderByFechaCreacionDesc(m.id).map(h->h.puestoRanking).orElse(m.posicionActualRanking);return new com.ligamunicipal.api.web.RankingItemDto(m.id,m.usuario.nombre,m.usuario.avatarUrl,m.puntosTotales,i+1,m.usuario.id.equals(usuarioId),anterior==0?0:anterior-(i+1));}).toList();}
 @Transactional public PartidoJornada cerrarJornada(UUID partidoId,UUID usuarioId){var partido=partidos.findById(partidoId).orElseThrow();requireAdmin(partido.equipo.id,usuarioId);if(!historialRanking.findByPartidoId(partidoId).isEmpty())return partido;var votosJornada=votos.findByPartidoId(partidoId);var porJugador=votosJornada.stream().collect(java.util.stream.Collectors.groupingBy(v->v.jugadorEvaluado.id));var medias=new HashMap<UUID,BigDecimal>();for(var entry:porJugador.entrySet()){var media=BigDecimal.valueOf(entry.getValue().stream().mapToInt(v->v.nota).average().orElse(0)).setScale(2,RoundingMode.HALF_UP);medias.put(entry.getKey(),media);var jugador=jugadores.findById(entry.getKey()).orElseThrow();var anterior=Optional.ofNullable(jugador.valorMercadoActual).orElse(BigDecimal.ZERO);var nuevo=media.compareTo(BigDecimal.valueOf(6))>=0?anterior.multiply(BigDecimal.valueOf(1.10)):media.compareTo(BigDecimal.valueOf(5))<0?anterior.multiply(BigDecimal.valueOf(.90)):anterior;jugador.mediaPuntos=media;jugador.variacionUltimaJornada=nuevo.subtract(anterior).setScale(2,RoundingMode.HALF_UP);jugador.valorMercadoActual=nuevo.setScale(2,RoundingMode.HALF_UP);jugadores.save(jugador);var historial=new HistorialMercado();historial.jugador=jugador;historial.partido=partido;historial.valorMercado=jugador.valorMercadoActual;historial.notaMediaJornada=media;historial.fueMvp=entry.getValue().stream().anyMatch(v->v.votoMvp);historialMercado.save(historial);}
 for(var alineacion:alineaciones.findByPartidoId(partidoId)){var puntos=BigDecimal.ZERO;for(var detalle:alineacion.detalles){var nota=medias.getOrDefault(detalle.jugador.id,BigDecimal.ZERO);detalle.puntosObtenidos=detalle.esCapitan?nota.multiply(BigDecimal.valueOf(2)):nota;puntos=puntos.add(detalle.puntosObtenidos);}alineacion.puntosJornada=puntos;alineaciones.save(alineacion);alineacion.miembro.puntosTotales=alineacion.miembro.puntosTotales.add(puntos);miembros.save(alineacion.miembro);}
 var ordenados=miembros.findByEquipoId(partido.equipo.id).stream().sorted(Comparator.comparing((MiembroEquipo m)->m.puntosTotales).reversed().thenComparing(m->m.id)).toList();for(var i=0;i<ordenados.size();i++){var miembro=ordenados.get(i);var nuevoPuesto=i+1;var anterior=historialRanking.findTopByMiembroIdOrderByFechaCreacionDesc(miembro.id).map(h->h.puestoRanking).orElse(miembro.posicionActualRanking);miembro.posicionActualRanking=nuevoPuesto;miembros.save(miembro);var historial=new HistorialRanking();historial.miembro=miembro;historial.partido=partido;historial.puntosAcumulados=miembro.puntosTotales;historial.puestoRanking=nuevoPuesto;historial.variacionPuestos=anterior==0?0:anterior-nuevoPuesto;historialRanking.save(historial);}partido.estado=EstadoPartido.CERRADO;return partidos.save(partido);}
 public VotoJornada votar(VotoJornada v){if(v.nota<-2||v.nota>10)throw new IllegalArgumentException("Nota fuera de rango");v.partido=partidos.findById(v.partido.id).orElseThrow();return votos.save(v);} public Map<String,Object> dashboard(UUID id){var e=equipos.findById(id).orElseThrow();var ps=plantilla(id);var js=jornadas(id);return Map.of("equipo",e,"plantilla",ps.size(),"partidos",js.size(),"checklist",Map.of("plantilla",!ps.isEmpty(),"invitacion",e.codigoInvitacion!=null,"precios",ps.stream().allMatch(x->x.valorMercadoActual!=null),"calendario",!js.isEmpty()));}
}
